import{_ as i,o as t,c as e,ag as r}from"./chunks/framework.IxO3mcwW.js";const o="/getbiji-docs/images/import-01.png",l="/getbiji-docs/images/import-02.png",s="/getbiji-docs/images/import-03.png",p="/getbiji-docs/images/import-04.png",d="/getbiji-docs/images/import-05.png",x=JSON.parse('{"title":"导入音视频","description":"","frontmatter":{},"headers":[],"relativePath":"capture/import.md","filePath":"capture/import.md","lastUpdated":1773147350000}'),n={name:"capture/import.md"};function c(m,a,h,u,_,g){return t(),e("div",null,[...a[0]||(a[0]=[r('<h1 id="导入音视频" tabindex="-1">导入音视频 <a class="header-anchor" href="#导入音视频" aria-label="Permalink to &quot;导入音视频&quot;">​</a></h1><blockquote><p>导入音视频上传，让冗长内容一键整理！</p></blockquote><p>把长达 3 小时的课程、会议或演讲音视频文件直接上传，让 AI 在后台完成转写与总结，从此告别繁琐手动整理。</p><h2 id="适用场景" tabindex="-1">适用场景 <a class="header-anchor" href="#适用场景" aria-label="Permalink to &quot;适用场景&quot;">​</a></h2><ul><li><strong>线上 &amp; 线下课程</strong>：将老师或讲师的整段授课录音转写为笔记，方便后期复习与检索</li><li><strong>商务会议 / 研讨会</strong>：上传录制文件，迅速产出结构化纪要，节省整理时间</li><li><strong>专题访谈 / 播客</strong>：还原对话原貌，按时间轴转写文字稿，便于后期创作与归档</li><li><strong>语音备忘录</strong>：平时录下的灵感或想法，自动转写为可搜索文本并智能汇总</li></ul><h2 id="app-端使用" tabindex="-1">APP 端使用 <a class="header-anchor" href="#app-端使用" aria-label="Permalink to &quot;APP 端使用&quot;">​</a></h2><ol><li>打开 App，点击首页底部+号，选择「导入音视频」</li></ol><div class="tip custom-block"><p class="custom-block-title">支持格式</p><p>支持主流音频 / 视频格式（MP3、WAV、M4A、MP4、MOV、AVI 等）</p></div><ol start="2"><li><p>可以从相册、本地文件中导入音视频内容</p></li><li><p>上传文件后，AI 会分析文件内容选择最佳的模板进行总结整理</p></li><li><p>完成后，AI 会生成音频对应的转写文字稿和总结笔记</p></li></ol><h2 id="从语音备忘录导入" tabindex="-1">从语音备忘录导入 <a class="header-anchor" href="#从语音备忘录导入" aria-label="Permalink to &quot;从语音备忘录导入&quot;">​</a></h2><p>iOS 用户可以从「语音备忘录」App 分享音频到 Get笔记：</p><ol><li>打开系统「语音备忘录」App</li><li>长按或点击要导入的录音</li><li>点击分享按钮</li><li>选择「Get笔记」即可导入</li></ol><h2 id="转写额度-文件时长" tabindex="-1">转写额度 &amp; 文件时长 <a class="header-anchor" href="#转写额度-文件时长" aria-label="Permalink to &quot;转写额度 &amp; 文件时长&quot;">​</a></h2><p>转写时长额度月初重新计算不累计，下月自动更新，PRO 会员到期后自动降为普通额度。</p><h2 id="网页端使用" tabindex="-1">网页端使用 <a class="header-anchor" href="#网页端使用" aria-label="Permalink to &quot;网页端使用&quot;">​</a></h2><ul><li>首页 - 导入音视频</li><li>知识库 - 添加 - 导入音视频</li><li>追加笔记 - 导入音视频</li></ul><h2 id="截图演示" tabindex="-1">截图演示 <a class="header-anchor" href="#截图演示" aria-label="Permalink to &quot;截图演示&quot;">​</a></h2><div style="display:flex;gap:10px;overflow-x:auto;"><img src="'+o+'" alt="导入入口" style="width:180px;border-radius:8px;"><img src="'+l+'" alt="选择文件" style="width:180px;border-radius:8px;"><img src="'+s+'" alt="上传中" style="width:180px;border-radius:8px;"><img src="'+p+'" alt="AI处理" style="width:180px;border-radius:8px;"><img src="'+d+'" alt="转写结果" style="width:180px;border-radius:8px;"></div>',18)])])}const P=i(n,[["render",c]]);export{x as __pageData,P as default};
